// En server.js - Agrega esta ruta si no existe
app.get('/api/pagos-pendientes/deuda/:jugadorId', verificarToken, async (req, res) => {
    const { jugadorId } = req.params;
    
    try {
        const result = await pool.query(
            `SELECT COALESCE(SUM(monto), 0) as total_deuda 
             FROM pagos_pendientes 
             WHERE jugador_id = $1 AND estado = 'pendiente'`,
            [jugadorId]
        );
        res.json({ total_deuda: parseFloat(result.rows[0].total_deuda) });
    } catch (error) {
        console.error('Error calculando deuda:', error);
        res.status(500).json({ error: error.message });
    }
});
